-- Check the imported table against the build that produced its CSV.
-- Generated by python -m ahah_ingest.sql_check from the output schema and the export contract.
--
-- It reads the table; it never repairs, replaces or promotes anything. The expected values
-- come from results/manifest.json, which is the build's own record, never from the loaded table.
--
-- What this establishes: the declared columns, types, nullability and order are present, the
-- natural key is unique and not null, no text contains the framing characters, the row count
-- matches, and the recomputed digest matches.
-- What it does not: the digest truncates each SHA-256 to eight bytes and adds the results, so
-- collisions and cancelling changes are possible. It detects accidental load corruption.

SET NOCOUNT ON;
SET XACT_ABORT ON;

-- STEP 1. EDIT. Paste this build's numbers from results/manifest.json (csv.rows, csv.digest.total).
IF OBJECT_ID(N'tempdb..#expected', N'U') IS NOT NULL DROP TABLE #expected;
CREATE TABLE #expected (name sysname PRIMARY KEY, row_count bigint NOT NULL,
                        digest_total decimal(38,0) NOT NULL, digest_version int NOT NULL);
INSERT INTO #expected (name, row_count, digest_total, digest_version) VALUES
    (N'ahah_datazone', 0, 0, 1)   -- EDIT: rows and total from manifest csv.digest
;

IF EXISTS (SELECT 1 FROM #expected WHERE digest_version <> 1)
    THROW 51000, 'This script implements digest definition version 1 only.', 1;
IF EXISTS (SELECT 1 FROM #expected WHERE row_count <= 0)
    THROW 51000, 'Expected row count and digest total have not been filled in from the manifest.', 1;

IF OBJECT_ID(N'tempdb..#result', N'U') IS NOT NULL DROP TABLE #result;
CREATE TABLE #result (table_name sysname, check_name nvarchar(200), expected nvarchar(200),
                      actual nvarchar(200), difference bigint NULL, passed bit NOT NULL);

-- ============================================================================================
-- ahah_datazone: structure, key, then the digest
-- ============================================================================================
IF OBJECT_ID(N'ahah_datazone', N'U') IS NULL
    INSERT INTO #result VALUES (N'ahah_datazone', N'table exists', N'a table', N'not found', NULL, 0);
ELSE
BEGIN
    -- 1. Structure. A digest cannot establish any of this. The variable name is fixed, so a
    -- loader that renames the table never touches it.
    DECLARE @declared TABLE (name sysname, ordinal int, type_name sysname,
                                     numeric_precision int, numeric_scale int, is_nullable bit);
    INSERT INTO @declared (name, ordinal, type_name, numeric_precision, numeric_scale, is_nullable) VALUES
    (N'ahah_version', 1, N'nvarchar', NULL, NULL, 0),
    (N'datazone_vintage', 2, N'smallint', NULL, NULL, 0),
    (N'datazone_code', 3, N'nvarchar', NULL, NULL, 0),
    (N'GP', 4, N'decimal', 38, 20, 1),
    (N'bluespace', 5, N'decimal', 38, 20, 1),
    (N'dentist', 6, N'decimal', 38, 20, 1),
    (N'fast_food', 7, N'decimal', 38, 20, 1),
    (N'gambling', 8, N'decimal', 38, 20, 1),
    (N'greenspace_active', 9, N'decimal', 38, 20, 1),
    (N'hospital', 10, N'decimal', 38, 20, 1),
    (N'leisure', 11, N'decimal', 38, 20, 1),
    (N'pharmacy', 12, N'decimal', 38, 20, 1),
    (N'pub_bar', 13, N'decimal', 38, 20, 1),
    (N'tobacco', 14, N'decimal', 38, 20, 1),
    (N'NO2', 15, N'decimal', 38, 20, 1),
    (N'PM10', 16, N'decimal', 38, 20, 1),
    (N'SO2', 17, N'decimal', 38, 20, 1),
    (N'greenspace', 18, N'decimal', 38, 20, 1),
    (N'off_licence', 19, N'decimal', 38, 20, 1),
    (N'ur', 20, N'tinyint', NULL, NULL, 1),
    (N'GP_rnk', 21, N'int', NULL, NULL, 1),
    (N'bluespace_rnk', 22, N'int', NULL, NULL, 1),
    (N'dentist_rnk', 23, N'int', NULL, NULL, 1),
    (N'fast_food_rnk', 24, N'int', NULL, NULL, 1),
    (N'gambling_rnk', 25, N'int', NULL, NULL, 1),
    (N'greenspace_active_rnk', 26, N'int', NULL, NULL, 1),
    (N'hospital_rnk', 27, N'int', NULL, NULL, 1),
    (N'leisure_rnk', 28, N'int', NULL, NULL, 1),
    (N'pharmacy_rnk', 29, N'int', NULL, NULL, 1),
    (N'pub_bar_rnk', 30, N'int', NULL, NULL, 1),
    (N'tobacco_rnk', 31, N'int', NULL, NULL, 1),
    (N'NO2_rnk', 32, N'int', NULL, NULL, 1),
    (N'PM10_rnk', 33, N'int', NULL, NULL, 1),
    (N'SO2_rnk', 34, N'int', NULL, NULL, 1),
    (N'greenspace_rnk', 35, N'int', NULL, NULL, 1),
    (N'GP_pct', 36, N'tinyint', NULL, NULL, 1),
    (N'bluespace_pct', 37, N'tinyint', NULL, NULL, 1),
    (N'dentist_pct', 38, N'tinyint', NULL, NULL, 1),
    (N'fast_food_pct', 39, N'tinyint', NULL, NULL, 1),
    (N'gambling_pct', 40, N'tinyint', NULL, NULL, 1),
    (N'greenspace_active_pct', 41, N'tinyint', NULL, NULL, 1),
    (N'hospital_pct', 42, N'tinyint', NULL, NULL, 1),
    (N'leisure_pct', 43, N'tinyint', NULL, NULL, 1),
    (N'pharmacy_pct', 44, N'tinyint', NULL, NULL, 1),
    (N'pub_bar_pct', 45, N'tinyint', NULL, NULL, 1),
    (N'tobacco_pct', 46, N'tinyint', NULL, NULL, 1),
    (N'NO2_pct', 47, N'tinyint', NULL, NULL, 1),
    (N'PM10_pct', 48, N'tinyint', NULL, NULL, 1),
    (N'SO2_pct', 49, N'tinyint', NULL, NULL, 1),
    (N'greenspace_pct', 50, N'tinyint', NULL, NULL, 1),
    (N'GP_dec', 51, N'smallint', NULL, NULL, 1),
    (N'bluespace_dec', 52, N'smallint', NULL, NULL, 1),
    (N'dentist_dec', 53, N'smallint', NULL, NULL, 1),
    (N'fast_food_dec', 54, N'smallint', NULL, NULL, 1),
    (N'gambling_dec', 55, N'smallint', NULL, NULL, 1),
    (N'greenspace_active_dec', 56, N'smallint', NULL, NULL, 1),
    (N'hospital_dec', 57, N'smallint', NULL, NULL, 1),
    (N'leisure_dec', 58, N'smallint', NULL, NULL, 1),
    (N'pharmacy_dec', 59, N'smallint', NULL, NULL, 1),
    (N'pub_bar_dec', 60, N'smallint', NULL, NULL, 1),
    (N'tobacco_dec', 61, N'smallint', NULL, NULL, 1),
    (N'NO2_dec', 62, N'smallint', NULL, NULL, 1),
    (N'PM10_dec', 63, N'smallint', NULL, NULL, 1),
    (N'SO2_dec', 64, N'smallint', NULL, NULL, 1),
    (N'greenspace_dec', 65, N'smallint', NULL, NULL, 1),
    (N'off_licence_dec', 66, N'smallint', NULL, NULL, 1),
    (N'domain_h', 67, N'decimal', 38, 20, 1),
    (N'domain_g', 68, N'decimal', 38, 20, 1),
    (N'domain_e', 69, N'decimal', 38, 20, 1),
    (N'domain_r', 70, N'decimal', 38, 20, 1),
    (N'domain_h_exp', 71, N'decimal', 38, 20, 1),
    (N'domain_g_exp', 72, N'decimal', 38, 20, 1),
    (N'domain_e_exp', 73, N'decimal', 38, 20, 1),
    (N'domain_r_exp', 74, N'decimal', 38, 20, 1),
    (N'domain_h_rnk', 75, N'int', NULL, NULL, 1),
    (N'domain_g_rnk', 76, N'int', NULL, NULL, 1),
    (N'domain_e_rnk', 77, N'int', NULL, NULL, 1),
    (N'domain_r_rnk', 78, N'int', NULL, NULL, 1),
    (N'domain_h_pct', 79, N'tinyint', NULL, NULL, 1),
    (N'domain_g_pct', 80, N'tinyint', NULL, NULL, 1),
    (N'domain_e_pct', 81, N'tinyint', NULL, NULL, 1),
    (N'domain_r_pct', 82, N'tinyint', NULL, NULL, 1),
    (N'domain_h_dec', 83, N'smallint', NULL, NULL, 1),
    (N'domain_g_dec', 84, N'smallint', NULL, NULL, 1),
    (N'domain_e_dec', 85, N'smallint', NULL, NULL, 1),
    (N'domain_r_dec', 86, N'smallint', NULL, NULL, 1),
    (N'ahah', 87, N'decimal', 38, 20, 1),
    (N'ahah_rnk', 88, N'int', NULL, NULL, 1),
    (N'ahah_pct', 89, N'tinyint', NULL, NULL, 1),
    (N'ahah_dec', 90, N'smallint', NULL, NULL, 1);

    INSERT INTO #result
    SELECT N'ahah_datazone', N'columns declared and in order', N'0 differences',
           CONVERT(nvarchar(200), COUNT(*)) + N' differences', COUNT(*), CASE WHEN COUNT(*) = 0 THEN 1 ELSE 0 END
    FROM (
        -- Bound to the one object being checked by OBJECT_ID, never by name alone: a table of
        -- the same name in another schema must not be able to satisfy this.
        SELECT d.name FROM @declared d
        LEFT JOIN (SELECT c.name, c.column_id, t.name AS type_name, c.precision, c.scale, c.is_nullable
                   FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
                   WHERE c.object_id = OBJECT_ID(N'ahah_datazone', N'U')) c
               ON c.name = d.name AND c.column_id = d.ordinal AND c.type_name = d.type_name
              AND (d.numeric_precision IS NULL
                   OR (c.precision = d.numeric_precision AND c.scale = d.numeric_scale))
              AND c.is_nullable = d.is_nullable
        WHERE c.name IS NULL
        UNION ALL
        SELECT c.name FROM sys.columns c
        WHERE c.object_id = OBJECT_ID(N'ahah_datazone', N'U')
          AND c.name NOT IN (SELECT name FROM @declared)
    ) AS differences;

    -- 2. The natural key: the digest is order independent, so a duplicated row and a missing
    -- one can cancel out.
    INSERT INTO #result
    SELECT N'ahah_datazone', N'natural key [ahah_version], [datazone_code] unique and not null', N'0 offending rows',
           CONVERT(nvarchar(200), COUNT_BIG(*)) + N' offending rows', COUNT_BIG(*),
           CASE WHEN COUNT_BIG(*) = 0 THEN 1 ELSE 0 END
    FROM (SELECT [ahah_version], [datazone_code] FROM ahah_datazone GROUP BY [ahah_version], [datazone_code] HAVING COUNT_BIG(*) > 1) AS duplicates;

    -- 3. Reserved framing characters in the text columns.
    INSERT INTO #result
    SELECT N'ahah_datazone', N'no reserved framing characters in text', N'0 rows',
           CONVERT(nvarchar(200), COUNT_BIG(*)) + N' rows', COUNT_BIG(*),
           CASE WHEN COUNT_BIG(*) = 0 THEN 1 ELSE 0 END
    FROM ahah_datazone
    WHERE DATALENGTH(REPLACE(REPLACE([ahah_version] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([ahah_version])
       OR DATALENGTH(REPLACE(REPLACE([datazone_code] COLLATE Latin1_General_100_BIN2_UTF8, NCHAR(0), N''), NCHAR(31), N'')) <> DATALENGTH([datazone_code]);

    -- 4. The row count and the digest, rendered as the CSV renders each row, NCHAR(0) for a
    -- null, fields joined with NCHAR(31) in contract order, hashed as UTF-8, the signed
    -- eight-byte prefixes summed as decimal.
    INSERT INTO #result
    SELECT N'ahah_datazone', N'row count', CONVERT(nvarchar(200), e.row_count),
           CONVERT(nvarchar(200), q.n), ABS(q.n - e.row_count),
           CASE WHEN q.n = e.row_count THEN 1 ELSE 0 END
    FROM #expected e CROSS JOIN (SELECT COUNT_BIG(*) AS n FROM ahah_datazone) AS q
    WHERE e.name = N'ahah_datazone';

    INSERT INTO #result
    SELECT N'ahah_datazone', N'row digest, definition version ' + CONVERT(nvarchar(10), e.digest_version),
           CONVERT(nvarchar(200), e.digest_total), CONVERT(nvarchar(200), ISNULL(q.total, 0)),
           CASE WHEN ISNULL(q.total, 0) = e.digest_total THEN 0 ELSE 1 END,
           CASE WHEN ISNULL(q.total, 0) = e.digest_total THEN 1 ELSE 0 END
    FROM #expected e CROSS JOIN (
        SELECT SUM(CONVERT(decimal(38,0), CONVERT(bigint, SUBSTRING(HASHBYTES('SHA2_256',
                   CONVERT(varchar(max), CONCAT_WS(NCHAR(31),
           CONVERT(nvarchar(max), ISNULL([ahah_version], NCHAR(0))),
           ISNULL(CONVERT(varchar(11), [datazone_vintage]), NCHAR(0)),
           ISNULL([datazone_code], NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [GP]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [bluespace]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [dentist]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [fast_food]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [gambling]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [greenspace_active]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [hospital]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [leisure]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [pharmacy]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [pub_bar]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [tobacco]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [NO2]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [PM10]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [SO2]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [greenspace]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [off_licence]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [ur]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [GP_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [bluespace_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [dentist_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [fast_food_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [gambling_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [greenspace_active_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [hospital_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [leisure_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [pharmacy_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [pub_bar_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [tobacco_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [NO2_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [PM10_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [SO2_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [greenspace_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [GP_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [bluespace_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [dentist_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [fast_food_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [gambling_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [greenspace_active_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [hospital_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [leisure_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [pharmacy_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [pub_bar_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [tobacco_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [NO2_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [PM10_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [SO2_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [greenspace_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [GP_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [bluespace_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [dentist_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [fast_food_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [gambling_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [greenspace_active_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [hospital_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [leisure_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [pharmacy_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [pub_bar_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [tobacco_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [NO2_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [PM10_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [SO2_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [greenspace_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [off_licence_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [domain_h]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [domain_g]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [domain_e]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [domain_r]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [domain_h_exp]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [domain_g_exp]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [domain_e_exp]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [domain_r_exp]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_h_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_g_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_e_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_r_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_h_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_g_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_e_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_r_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_h_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_g_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_e_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [domain_r_dec]), NCHAR(0)),
           ISNULL(CONVERT(varchar(40), [ahah]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [ahah_rnk]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [ahah_pct]), NCHAR(0)),
           ISNULL(CONVERT(varchar(11), [ahah_dec]), NCHAR(0))) COLLATE Latin1_General_100_BIN2_UTF8)), 1, 8)))) AS total
        FROM ahah_datazone) AS q
    WHERE e.name = N'ahah_datazone';
END

-- ============================================================================================
-- The result. A skipped check is not a pass, so an absent row fails the count below.
-- ============================================================================================
SELECT table_name, check_name, expected, actual, difference,
       CASE passed WHEN 1 THEN 'pass' ELSE 'FAIL' END AS outcome
FROM #result ORDER BY table_name, check_name;

DECLARE @failed int = (SELECT COUNT(*) FROM #result WHERE passed = 0);
DECLARE @ran int = (SELECT COUNT(*) FROM #result);
IF @failed > 0 OR @ran <> 5
    THROW 51000, 'The imported table does not match the build: see the result above.', 1;
